			title = "Resumen",
			text = [=[Naralex es un druida {link:night-elves}elfo de la noche{/link} que llegó a las {link:wailing-caverns}Cuevas de los Lamentos{/link} con un propósito noble. Creía que, por medio del {link:emerald-dream}Sueño Esmeralda{/link} y de los manantiales ocultos de las cuevas, podría hacer florecer de nuevo {link:the-barrens}Los Baldíos{/link}. Entró en el sueño y no volvió. Su visión de renacimiento se convirtió en pesadilla, y todavía yace en las profundidades de las cuevas, perdido entre el sueño y la locura. La pesadilla fluye de él hacia las aguas y las bestias.]=],
		},
		{
			title = "Importancia",
			text = [=[Naralex es el origen de la corrupción de {link:the-barrens}Los Baldíos{/link}, y su primera víctima. Sus propios discípulos se han convertido en sus carceleros. Mientras duerma, las cuevas engendrarán monstruos y los oasis llevarán su enfermedad por las llanuras. Su destino es también una advertencia para todos los druidas de {link:azeroth}Azeroth{/link}: el Sueño no es tan seguro como creían.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Llevó a sus discípulos a las {link:wailing-caverns}Cuevas de los Lamentos{/link} para sanar {link:the-barrens}Los Baldíos{/link}.
• Entró en el {link:emerald-dream}Sueño Esmeralda{/link} y quedó atrapado en una pesadilla.
• A través de sus sueños, bestias descarriadas y ectoplasmas entraron en el mundo de la vigilia.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se escribe aquí de la vida de Naralex antes de las cuevas. Esta entrada recoge solo lo que revelan sus discípulos y su sueño.]=],
		},
	},
	chapters = {
		{
			title = "La pesadilla",
			hint = "Averigüe por los discípulos fieles por qué duerme Naralex.",
			text = [=[Los discípulos que siguieron fieles cuentan el mismo relato. Su amo aspiraba a entrar en el Sueño y reverdecer la tierra áspera. Algo salió terriblemente mal. A medida que Naralex se hundía más en su pesadilla, extrañas bestias surgieron de debajo de {link:the-barrens}Los Baldíos{/link} hacia las cuevas, y los druidas que lo amaban cambiaron.]=],
		},
		{
			title = "El despertar",
			hint = "Proteja al discípulo mientras celebra el rito del despertar.",
			text = [=[Cuando los cuatro {link:druids-of-the-fang}señores del Colmillo{/link} murieron, el último discípulo fiel abrió el camino hasta la cámara de su amo y penetró en el Sueño para encontrarlo. Las pesadillas se alzaron para detenerlo: serpientes, légamos y, por último, una criatura monstruosa salida del agua. Cuando cayó, Naralex gritó que estaba despierto. Del cuerpo de la bestia salió un fragmento verde en el que parecía arremolinarse humo, un fragmento del Sueño que mostraba una pesadilla.]=],
		},
	},
	mentions = {
		{ text = "El fragmento reluciente" },
		{
			text = [=[En pesadillas, el fragmento llevado a {link:thunder-bluff}Cima del Trueno{/link}]=],
		},
		{
			text = [=[En pesadillas, el fragmento llevado a {link:darnassus}Darnassus{/link}]=],
		},
	},
	bonds = {
		{ id = "disciple-of-naralex", name = "Discípulo de Naralex", note = "su alumno fiel" },
		{ id = "lord-serpentis", name = "Lord Serpentis", note = "su alumno, ahora su carcelero" },
		{ id = "mutanus-the-devourer", name = "Mutanus el Devorador", note = "la pesadilla que guarda su sueño" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "leyó el fragmento de su pesadilla" },
	},
})

Translate("esMX", "disciple-of-naralex", {
	title = "Discípulo de Naralex",
	subtitle = "El último discípulo fiel",
	found = "La entrada de las Cuevas de los Lamentos",
	hint = [=[Hable con el discípulo que espera en la entrada de las Cuevas de los Lamentos.]=],
	allegiance = "Discípulos de Naralex · Tauren",
	sections = {
		{
			title = "Resumen",
			text = [=[El Discípulo de Naralex es un druida {link:tauren}tauren{/link}, uno de los pocos seguidores de {link:naralex}Naralex{/link} a quienes la pesadilla no ha retorcido. Espera justo dentro de las {link:wailing-caverns}Cuevas de los Lamentos{/link}. Su amo vuelve a dormir, dice, y bestias reptilianas se filtran de sus sueños a la tierra. Hay que despertar a Naralex de su pesadilla o se perderá para siempre, y se desatará un gran mal. Pero el Discípulo no puede celebrar el rito del despertar mientras vivan sus hermanos corrompidos. Primero deben morir los cuatro {link:druids-of-the-fang}señores del Colmillo{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[El Discípulo es la única esperanza del soñador. Conoce el rito que puede hacer volver a {link:naralex}Naralex{/link}, y ha mantenido la fe a pesar de todo aquello en que se han convertido las cuevas. Habla de ellas con pesar: antes un templo de promesa para {link:the-barrens}Los Baldíos{/link}, ahora salas de pesadilla.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Bendice con la marca de lo salvaje a quienes quieren entrar en las cuevas.
• Pide la muerte de los cuatro {link:druids-of-the-fang}señores del Colmillo{/link}.
• Destierra los espíritus de los señores del Colmillo caídos dentro de un círculo de fuego.
• Penetra en el {link:emerald-dream}Sueño Esmeralda{/link} para despertar a su amo.]=],
		},
	},
	chapters = {
		{
			title = "El rito del despertar",
			hint = [=[Mate a los señores del Colmillo y luego proteja al Discípulo en su camino hacia Naralex.]=],
			text = [=[Cuando los {link:druids-of-the-fang}señores del Colmillo{/link} estuvieron muertos, el Discípulo declaró que no toda esperanza estaba perdida, pero que no podía terminar el rito solo. Abrió el camino por las cuevas, purificándolas a su paso, mientras las pesadillas de su amo enviaban víboras y cosas peores contra él. Junto a {link:naralex}Naralex{/link} se sumergió en el Sueño. El ritual fue largo, y los ataques se hicieron más feroces, hasta que por fin el soñador despertó.]=],
		},
	},
	mentions = {
		{ text = "Pieles descarriadas, que pide su compañero Nalpak" },
		{ text = "Erradicación descarriada, que pide su compañera Ebru" },
	},
	bonds = {
		{ id = "naralex", name = "Naralex", note = "su amo" },
		{ id = "lord-serpentis", name = "Lord Serpentis", note = "un hermano que cayó" },
	},
})

