Translate("esMX", "kresh", {
	title = "Kresh",
	subtitle = "La tortuga intacta",
	found = "El río subterráneo de las Cuevas de los Lamentos",
	hint = "Busque a la vieja tortuga que nada en el río subterráneo.",
